import itertools
def orders(h, w, garage):
    """How many orders of filling the garage cells work: each cell, when its turn comes, can be reached from a cell
    outside the garage by steps up, down, left or right through cells that are not filled yet."""
    garage = list(garage); outside = [(r, c) for r in range(1, h + 1) for c in range(1, w + 1) if (r, c) not in garage]
    def reach(t, filled):
        seen, stack = {t}, [t]
        while stack:
            r, c = stack.pop()
            if (r, c) in outside: return True
            for n in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if 1 <= n[0] <= h and 1 <= n[1] <= w and n not in seen and n not in filled: seen.add(n); stack.append(n)
        return False
    good = []
    for p in itertools.permutations(garage):
        filled, ok = set(), True
        for t in p:
            if not reach(t, filled): ok = False; break
            filled.add(t)
        if ok: good.append(p)
    return good
result = orders(1, 6, [(1, c) for c in range(2, 7)])[0][0][1] - 1

